from collections import deque
def flood(I, boxc):
    h,w=len(I),len(I[0])
    # cells that can escape to border moving only through non-boxc cells... standard flood from border over non-boxc
    out=set(); q=deque()
    for c in range(w):
        for rr,(r,c0) in enumerate([(0,c),(h-1,c)]):
            if I[r][c]!=boxc and (r,c) not in out: out.add((r,c)); q.append((r,c))
    for r in range(h):
        for cc in [(0,r),(w-1,r)]:
            pass
    for r in range(h):
        for cc in (0,w-1):
            if I[r][cc]!=boxc and (r,cc) not in out: out.add((r,cc)); q.append((r,cc))
    while q:
        r,c=q.popleft()
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            nr,nc=r+dr,c+dc
            if 0<=nr<h and 0<=nc<w and I[nr][nc]!=boxc and (nr,nc) not in out:
                out.add((nr,nc)); q.append((nr,nc))
