G=load()

def solve(I):
    O=[r[:] for r in I]; h,w=len(I),len(I[0])
    vals=set(x for r in I for x in r)
    bg=max(vals,key=lambda v:sum(r.count(v) for r in I))
    boxc=[v for v in vals if v!=bg][0]
    pts=[(r,c) for r in range(h) for c in range(w) if I[r][c]==boxc]
    r0,r1=min(p[0] for p in pts),max(p[0] for p in pts)
    c0,c1=min(p[1] for p in pts),max(p[1] for p in pts)
    # interior = strict bbox interior minus cells reachable from border via non-boxc walk (4-dir)
    bad=set(); dq=deque()
    for rr in range(h):
        for cc in (0,w-1):
            if I[rr][cc]!=boxc and (rr,cc) not in bad: bad.add((rr,cc)); dq.append((rr,cc))
    for cc in range(w):
        for rr in (0,h-1):
            if I[rr][cc]!=boxc and (rr,cc) not in bad: bad.add((rr,cc)); dq.append((rr,cc))
    while dq:
        r,c=dq.popleft()
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            nr,nc=r+dr,c+dc
            if 0<=nr<h and 0<=nc<w and I[nr][nc]!=boxc and (nr,nc) not in bad:
                bad.add((nr,nc)); dq.append((nr,nc))
    inter={(r,c) for r in range(r0+1,r1) for c in range(c0+1,c1)}-bad
    for rr,cc in inter: O[rr][cc]=4
    # ring cells not boxc form gap runs
    ring=[]
    for c in range(c0,c1+1): ring+= [(r0,c),(r1,c)]
    for r in range(r0,r1+1): ring+= [(r,c0),(r,c1)]
    gaps=sorted(set(ring)-set(pts))
    seen=set(); runs=[]
    for g in gaps:
        if g in seen: continue
        st=[g]; comp=[g]; seen.add(g)
        while st:
            qq=st.pop()
            for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                n=(qq[0]+dr,qq[1]+dc)
                if n in set(gaps) and n not in seen:
                    seen.add(n); st.append(n); comp.append(n)
        runs.append(comp)
    def shoot(er,ec,ev,eh):
        rr,cc=er+ev,ec+eh
        while 0<=rr<h and 0<=cc<w:
            O[rr][cc]=4; rr+=ev; cc+=eh
    for run in runs:
        cells=sorted(run)
        vert_wall = len({p[0] for p in cells})==1   # horizontal wall => rays vertical
        mid=sum(p[0] for p in cells)/len(cells) if vert_wall else sum(p[1] for p in cells)/len(cells)
        ev=-1 if (cells[0][0]==r0) else (1 if cells[-1][0]==r1 else -1 if cells[0][1]==c0 else 1)
        for e,sig in [(cells[0],-1),(cells[-1],1)]:
            ah=int(sig*round(e[0]-mid)/max(1,abs(round(e[0]-mid)))) if abs(e[0]-mid)>1e-9 else 0
            ah_=int(sig*round(e[1]-mid)/max(1,abs(round(e[1]-mid)))) if abs(e[1]-mid)>1e-9 else 0
            shoot(e[0],e[1],ev,ah if vert_wall else ah_)
    return O

